import{z as o,x as l,o as B,c as p,q as A,j as i,D as r,d as e,s as t,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"缓存友好的算法","description":"","frontmatter":{"title":"缓存友好的算法","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ae-cache-friendly.md","filePath":"cs/ae-cache-friendly.md","lastUpdated":1791063341000}'),d={name:"cs/ae-cache-friendly.md"};function D(m,a,c,h,f,C){const s=l("Mermaid");return B(),p("div",null,[a[2]||(a[2]=A('<h1 id="缓存友好的算法" tabindex="-1">缓存友好的算法 <a class="header-anchor" href="#缓存友好的算法" aria-label="Permalink to &quot;缓存友好的算法&quot;">​</a></h1><div class="epigraph"><p>让计算变快的上限是屋顶，让数据变近的收益是斜率；很多时候该省的不是乘加，而是搬运。</p><footer>—— 据 Williams, Waterman, and Patterson, CACM 2009；Drepper, What Every Programmer Should Know About Memory, 2007 整理</footer></div><p><a href="/cs/ae-constant-optimization">上一课</a>把常数拆成指令数与每指令成本，但那笔账里藏着常最大的一个成本项：访存。寄存器与 L1 以个位周期计，DRAM 以几百周期计；同一份算法，摆数据的姿势不同，时间能差出一个数量级。本课把「缓存友好」写成可操作的三件事——布局、分块、顺序访问——并接上<a href="/cs/par-roofline-map">roofline 的深化与收束</a>那幅屋顶图：算术强度不够时，缺的不是算力而是字节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指令数已经压过的代码仍然慢，原因有三类。指针追链：链表与树每次解引用都可能 miss，地址在下一次访问之前未知；错序遍历：矩阵按与存储序不匹配的方向扫，每一步都换行失效，空间局部性全丢；布局错位：结构体数组让热循环把整条结构体扛进缓存却只用一个字段。<a href="/cs/cache-miss-types">缺失分类</a>给了词汇：这里的对象主要是容量与冲突缺失，而它们不是常数——miss 的价格随层级差百倍，且能被算法改写。不这么做会错在哪：只盯着乘加计数做优化，却在每次迭代里付一次 DRAM 访问，省下的那几条指令根本不够填坑。</p><p><span class="marginnote">常见误区：初学者容易把「优化」等同于「减少乘加次数」，实际上把三重循环的内外层换个顺序（ikj 序）一条指令都没省，只因把访问改成沿内存方向滑动，就能快数倍——省的是每次换行缓存失效的那几十到几百周期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一件事，紧凑布局。把指针结构换成数组下标：隐式堆、数组化的邻接表，孩子与邻居就是一段连续内存；热字段与冷字段拆开，让热循环只装它要的字节；<a href="/cs/alignment-access">对齐与非对齐访问</a>决定一行缓存装得下几条记录，padding 不是小事。</p><p>第二件事，分块（tiling）。矩阵乘按缓存大小取块，让一块数据装入后被算够本再换下一块；<a href="/cs/loop-invariant">循环不变式</a>式的复用在数据上的对应物就是「复用装入缓存的那份字节」。同样的原理写进结构：B 树节点做成一页、二叉堆用隐式数组布局，都是把「子问题恰好装进一层缓存」铸进数据结构。</p><p>第三件事，顺序访问喂预取器。硬件预取器认固定的步长；顺序扫描几乎免费，乱序与链式访问让它哑火，见<a href="/cs/cache-prefetch">预取</a>。</p><p>最后用递归分块收尾：<a href="/cs/cache-oblivious">缓存无关结构</a>让同一份代码在各层缓存上都自动分块，免去按机器调参。</p>',11)),(B(),i(n,null,{default:r(()=>[t(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAYOUT%5B%22%E5%B8%83%E5%B1%80%EF%BC%9A%E6%95%B0%E7%BB%84%E5%8C%96%E3%80%81%E5%86%B7%E7%83%AD%E6%8B%86%E5%88%86%E3%80%81%E5%AF%B9%E9%BD%90%22%5D%20--%3E%20BLOCK%5B%22%E5%88%86%E5%9D%97%EF%BC%9A%E5%B7%A5%E4%BD%9C%E9%9B%86%E8%A3%85%E8%BF%9B%E4%B8%80%E5%B1%82%E7%BC%93%E5%AD%98%22%5D%0A%20%20BLOCK%20--%3E%20SEQ%5B%22%E9%A1%BA%E5%BA%8F%E8%AE%BF%E9%97%AE%EF%BC%9A%E6%AD%A5%E9%95%BF%E8%A7%84%E6%95%B4%E5%96%82%E9%A2%84%E5%8F%96%22%5D%0A%20%20SEQ%20--%3E%20MI%5B%22%E7%BC%BA%E5%A4%B1%E5%88%86%E7%B1%BB%EF%BC%9A%E5%AE%B9%E9%87%8F%E3%80%81%E5%86%B2%E7%AA%81%E3%80%81%E5%BC%BA%E5%88%B6%22%5D%0A%20%20MI%20--%3E%20ROOF%5B%22roofline%20%E9%AA%8C%E6%94%B6%EF%BC%9A%E5%BC%BA%E5%BA%A6%E4%B8%8E%E5%B1%8B%E9%A1%B6%22%5D%0A%20%20ROOF%20--%3E%7C%E5%BC%BA%E5%BA%A6%E4%B8%8D%E8%B6%B3%7C%20LAYOUT%0A%20%20ROOF%20--%3E%7C%E7%82%B9%E5%B7%B2%E8%B4%B4%E5%B1%8B%E9%A1%B6%7C%20DONE%5B%22%E6%8D%A2%E4%B8%8B%E4%B8%80%E5%A4%84%E7%93%B6%E9%A2%88%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("miss 为什么主导：一次 DRAM 访问约两百到三百周期，够做几百次浮点乘加。算法强度（每字节几次运算）低于脊点 \\(I^{*}=F/B\\) 时，程序贴在带宽斜线上，SIMD 与多核都抬不动它——这正是屋顶图给出的判决，也是向量化要求规整布局的原因（见"),E("a",{href:"/cs/par-simd-vectorization"},"SIMD 与向量化"),e("）。分块为什么成立：装入成本被块内的重复计算摊薄，强度上升，工作点右移；经典结果是分块把矩阵乘的缺失从 \\(\\Theta(n^3)\\) 压到 \\(O(n^3/\\sqrt{M})\\)（\\(M\\) 为缓存可容纳的元素数）。顺序访问为什么便宜：预取把 miss 藏进计算后面，等效延迟趋近 L1；换成本质是每元素一次访存对一次顺带装载。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉账（Drepper 2007 的口径）：L1 命中约 4 周期，DRAM 约 200–300 周期。8 字节指针的链表换成连续数组后，遍历常快 5–10 倍——不是玄学，是把每元素一次不可预取的访存，换成一次顺带预取的顺序流。")],-1)),a[6]||(a[6]=E("p",null,"方法一节的图回答「缓存友好按哪三件事操作」，下面这张回答另一个问题：分块到底怎么把缺失次数压下来。",-1)),(B(),i(n,null,{default:r(()=>[t(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E7%BC%93%E5%AD%98%E4%B8%80%E6%AC%A1%E8%A3%85%E5%BE%97%E4%B8%8B%20M%20%E4%B8%AA%E5%85%83%E7%B4%A0%22%5D%20--%3E%20B%5B%22%E5%8F%96%E5%9D%97%20b%20x%20b%2C%20%E4%BF%9D%E8%AF%81%203b%5E2%20%E2%89%A4%20M%22%5D%0A%20%20B%20--%3E%20LOAD%5B%22%E6%8A%8A%20A%20%E7%9A%84%E5%9D%97%E4%B8%8E%20B%20%E7%9A%84%E5%9D%97%E5%90%84%E8%A3%85%E5%85%A5%E4%B8%80%E6%AC%A1%22%5D%0A%20%20LOAD%20--%3E%20REUSE%5B%22%E5%9D%97%E5%86%85%E6%89%80%E6%9C%89%E5%86%85%E7%A7%AF%E7%AE%97%E5%AE%8C%E6%89%8D%E6%8D%A2%E5%9D%97%22%5D%0A%20%20REUSE%20--%3E%20PAY%5B%22%E4%B8%80%E6%AC%A1%E6%90%AC%E8%BF%90%E6%8D%A2%E5%9B%9E%20b%5E2%20%E6%AC%A1%E9%87%8D%E7%94%A8%22%5D%0A%20%20PAY%20--%3E%20LOW%5B%22%E7%BC%BA%E5%A4%B1%E4%BB%8E%20%CE%98(n%5E3)%20%E9%99%8D%E5%88%B0%20O(n%5E3%2F%E2%88%9AM)%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">数字实例：L1 数据缓存 32 KB、double 占 8 字节、三个块同住时，\\(3b^2\\times 8\\le 32768\\) 解得 \\(b\\le 36\\)——这就是工程上块大小常取 32 或 48 的来历：不是魔法数，是「装得下」的算术。</span></p><p><span class="marginnote">直觉类比：分块像写论文查资料——把要用的三本书一次抱到桌上，写完所有相关段落再换书；朴素循环则是每查一个字就跑一趟书架，跑腿（访存）的时间远超查字（计算）本身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SIMD 指令本身，那是<a href="/cs/par-simd-vectorization">SIMD 与向量化</a>的事；但次序不能反——先有规整布局，向量化才有资格发生。分块参数依赖机器：写死的块大小换台机器就不再最优，取值要靠基准课的纪律测定；缓存无关结构免去调参，代价是更大的常数。多核共享缓存下的争用、NUMA 上的摆放，属并行课程，本课不展开。渐近阶不动是前提：缓存友好改善的是同一阶下的常数，把 \\(\\Theta(n^2)\\) 改成 \\(\\Theta(n\\log n)\\) 仍然是选型课的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>常数账的最大项常是访存：miss 以百周期计，乘加以周期计，先看强度再谈指令。</li><li>三件事：紧凑布局（数组化、冷热拆分、对齐）、分块提强度、顺序访问喂预取器。</li><li>分块把矩阵乘缺失从 \\(\\Theta(n^3)\\) 压到 \\(O(n^3/\\sqrt{M})\\)；「节点装进一页」是同一原理的结构化。</li><li>roofline 是验收标准：强度不足时，SIMD 与多核都上不去。</li><li>出处：Lam, Rothberg, and Wolf, ASPLOS 1991；Frigo, Leiserson, Prokop, and Ramachandran, FOCS 1999；Drepper 2007。</li></ul>',6))])}const F=o(d,[["render",D]]);export{b as __pageData,F as default};
